  'desmaio.avo':[['Grandpa Chico','Wake up, {nome}! Have a sip of water and get back on the road.']], 'desmaio.so':[['{nome}','Phew... A sip of water and off we go again.']],
  'fim.tempo':'Time', 'fim.inimigos':'Enemies beaten', 'fim.cordeis':'Booklets', 'fim.proxima':'Next level', 'fim.menu':'Back to menu',
