function preencher(s,v){
  if(Array.isArray(s)) return s.map(x=>preencher(x,v));
  if(typeof s!=='string') return s;
  const h=(typeof heroi!=='undefined' && heroi) || null, g=v.g || (h ? h.g : 'o');
  return s.replace(/\{g:([^|}]*)\|([^}]*)\}/g,(_,m,f)=>g==='a'?f:m).replace(/\{(\w+)\}/g,(tudo,n)=>{
    if(v[n]!=null) return v[n];
    if(n==='nome' && h) return h.nome;
    if(n==='trato' && h) return t(`pers.${h.id}.trato`);
    return tudo;
  });
}
function t(k,v={}){
  const s=(TEXTOS[idioma] && TEXTOS[idioma][k]!==undefined) ? TEXTOS[idioma][k] : TEXTOS.pt[k];
  return s===undefined ? k : preencher(s,v);
}
function idiomaInicial(){
  const salvo=(store.get(K_PREF)||{}).idioma;
  if(IDIOMAS[salvo]) return salvo;
  const nav=(navigator.language||'pt').slice(0,2).toLowerCase();
  return IDIOMAS[nav] ? nav : 'pt';
}
// textos fixos do HTML: data-t (texto), data-t-html (com marcação), data-t-aria (aria-label)
function traduzirPagina(){
  document.documentElement.lang=LANG_HTML[idioma];
  for(const e of document.querySelectorAll('[data-t]')) e.textContent=t(e.dataset.t);
  for(const e of document.querySelectorAll('[data-t-html]')) e.innerHTML=t(e.dataset.tHtml);
  for(const e of document.querySelectorAll('[data-t-aria]')) e.setAttribute('aria-label',t(e.dataset.tAria));
}
idioma=idiomaInicial();
